**Media Management** cho Product thông qua ProductMedia entity.

**1. Thêm Media mới**:
```go
func (uc *ProductUsecase) AddMedia(ctx context.Context, productID uint64, mediaURLs []string, mediaTypes []string) error {
    // Validate
    if len(mediaURLs) != len(mediaTypes) {
        return errors.New("mediaURLs and mediaTypes length mismatch")
    }

    // Get current media count
    existingMedia, _ := uc.mediaRepo.GetByProduct(ctx, productID)
    nextOrder := len(existingMedia)

    // Create media records
    for i, url := range mediaURLs {
        media := &ProductMedia{
            ProductID: productID,
            MediaURL:  url,
            MediaType: mediaTypes[i], // "image" or "video"
            IsMain:    len(existingMedia) == 0 && i == 0, // Ảnh đầu làm main nếu chưa có ảnh nào
            Order:     nextOrder + i,
        }

        err := uc.mediaRepo.Create(ctx, media)
        if err != nil {
            return err
        }
    }

    return nil
}
```

**2. Set Main Image (ảnh đại diện)**:
```go
func (uc *ProductUsecase) SetMainImage(ctx context.Context, productID, mediaID uint64) error {
    // Bỏ IsMain của tất cả ảnh cũ
    err := uc.db.Exec(
        "UPDATE product_media SET is_main = false WHERE product_id = ? AND deleted_at IS NULL",
        productID).Error
    if err != nil {
        return err
    }

    // Set IsMain cho ảnh mới
    media, err := uc.mediaRepo.GetByID(ctx, mediaID)
    if err != nil {
        return err
    }

    if media.ProductID != productID {
        return errors.New("media does not belong to this product")
    }

    media.IsMain = true
    return uc.mediaRepo.Update(ctx, media)
}
```

**3. Reorder Media (sắp xếp lại thứ tự)**:
```go
func (uc *ProductUsecase) ReorderMedia(ctx context.Context, productID uint64, mediaIDs []uint64) error {
    // Validate all media belong to product
    existingMedia, _ := uc.mediaRepo.GetByProduct(ctx, productID)
    if len(mediaIDs) != len(existingMedia) {
        return errors.New("must provide all media IDs")
    }

    // Update order
    for i, mediaID := range mediaIDs {
        err := uc.db.Exec(
            "UPDATE product_media SET \"order\" = ? WHERE id = ? AND product_id = ?",
            i, mediaID, productID).Error
        if err != nil {
            return err
        }
    }

    return nil
}
```

**4. Xóa Media**:
```go
func (uc *ProductUsecase) DeleteMedia(ctx context.Context, productID, mediaID uint64) error {
    media, err := uc.mediaRepo.GetByID(ctx, mediaID)
    if err != nil {
        return err
    }

    if media.ProductID != productID {
        return errors.New("media does not belong to this product")
    }

    // Soft delete
    err = uc.mediaRepo.Delete(ctx, mediaID)
    if err != nil {
        return err
    }

    // Nếu xóa main image, set ảnh đầu tiên còn lại làm main
    if media.IsMain {
        remainingMedia, _ := uc.mediaRepo.GetByProduct(ctx, productID)
        if len(remainingMedia) > 0 {
            remainingMedia[0].IsMain = true
            uc.mediaRepo.Update(ctx, &remainingMedia[0])
        }
    }

    // Reorder remaining media
    remainingMedia, _ := uc.mediaRepo.GetByProduct(ctx, productID)
    for i, m := range remainingMedia {
        if m.Order != i {
            m.Order = i
            uc.mediaRepo.Update(ctx, &m)
        }
    }

    return nil
}
```

