**Amenities** (tiện ích xung quanh) có quan hệ Many-to-Many với Product qua bảng junction `product_amenity`.

**1. Add Amenities to Product**:
```go
func (uc *ProductUsecase) AddAmenities(ctx context.Context, productID uint64, amenityIDs []uint64) error {
    // Validate product exists
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    // Validate amenities exist
    for _, amenityID := range amenityIDs {
        amenity, err := uc.amenityRepo.GetByID(ctx, amenityID)
        if err != nil {
            return fmt.Errorf("amenity %d not found", amenityID)
        }
        if !amenity.Active {
            return fmt.Errorf("amenity %d is inactive", amenityID)
        }
    }

    // Insert vào bảng junction product_amenity
    for _, amenityID := range amenityIDs {
        // Check duplicate
        var count int64
        uc.db.Table("product_amenity").
            Where("product_id = ? AND amenity_id = ?", productID, amenityID).
            Count(&count)

        if count > 0 {
            continue // Skip if already exists
        }

        err := uc.db.Exec(
            "INSERT INTO product_amenity (product_id, amenity_id) VALUES (?, ?)",
            productID, amenityID).Error
        if err != nil {
            return err
        }
    }

    return nil
}
