        var amenities []domain.Amenity
        err = tx.Where("id IN (?) AND active = true AND deleted_at IS NULL", amenityIDs).
            Find(&amenities).Error
        if err != nil {
            return err
        }

        if len(amenities) != len(amenityIDs) {
            return errors.New("some amenities not found or inactive")
        }

        // Bulk insert
        for _, amenityID := range amenityIDs {
            err = tx.Exec(
                "INSERT INTO product_amenity (product_id, amenity_id) VALUES (?, ?)",
                productID, amenityID).Error
            if err != nil {
                return err
            }
        }

        return nil
    })
}
