**5. Business Logic Validation**:
```go
func ValidateProductBusinessRules(ctx context.Context, product *Product, db *gorm.DB) error {
    // ApartmentID và AssetId không thể cùng lúc != nil
    if product.ApartmentID != nil && product.AssetId != nil {
        return errors.New("product cannot link to both apartment and asset")
    }

    // HouseInfo chỉ có khi PropertyType là nhà/biệt thự
    if product.PropertyTypeId != nil {
        var propertyType PropertyType
        db.First(&propertyType, product.PropertyTypeId)

        isHouse := strings.Contains(strings.ToLower(propertyType.Name), "nhà") ||
                   strings.Contains(strings.ToLower(propertyType.Name), "biệt thự")

        if !isHouse && product.HouseInfo != nil {
            return errors.New("house_info only for house/villa property type")
        }
    }

    // Apartment chỉ có khi PropertyType là căn hộ
    if product.PropertyTypeId != nil && product.ApartmentID != nil {
        var propertyType PropertyType
        db.First(&propertyType, product.PropertyTypeId)

        isApartment := strings.Contains(strings.ToLower(propertyType.Name), "căn hộ") ||
                       strings.Contains(strings.ToLower(propertyType.Name), "chung cư")

        if !isApartment {
            return errors.New("apartment_id only for apartment property type")
        }
    }

    // If sold, must have transaction
    if product.SaleStatus == enums.EProductSold && product.SaleTransactionID == nil {
        return errors.New("sold product must have sale_transaction_id")
    }
    if product.RentStatus == enums.EProductRented && product.RentTransactionID == nil {
        return errors.New("rented product must have rent_transaction_id")
    }

    // Validate transaction if provided
    if product.SaleTransactionID != nil {
        var txn Transaction
        err := db.First(&txn, *product.SaleTransactionID).Error
        if err != nil {
            return errors.New("sale_transaction not found")
        }
        if txn.ProductId == nil || *txn.ProductId != product.ID {
            return errors.New("transaction does not belong to this product")
        }
    }

    return nil
}
