**Soft Delete** và **Archive** Product có mục đích khác nhau:

**1. Soft Delete (xóa mềm)**:
```go
func (uc *ProductUsecase) Delete(ctx context.Context, productID uint64) error {
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    // Check permission
    profileID := _utils.GetProfileIdWithContext(ctx)
    if product.OwnerID != profileID {
        return errors.New("no permission to delete")
    }

    // Check if product has active transactions
    if product.SaleStatus == enums.EProductSelling || product.RentStatus == enums.EProductRenting {
        return errors.New("cannot delete product with active listings")
    }

    // Soft delete (set deleted_at = NOW())
    err = uc.productRepo.Delete(ctx, productID)
    if err != nil {
        return err
    }

    // Hide all posts
    posts, _ := uc.postRepo.GetByProduct(ctx, productID)
    for _, post := range posts {
        uc.postRepo.Delete(ctx, post.ID) // Soft delete posts too
    }

    // Create history
    history := &RecordHistory{
        RecordID:   &productID,
        RecordType: enums.ERecordTypeProduct,
        ActionType: enums.EHistoryActionDelete,
        Content:    []string{fmt.Sprintf("Product deleted: %s", product.Name)},
    }
    uc.historyRepo.Create(ctx, history)

    return nil
}
```

**2. Archive (lưu trữ)**:
```go
func (uc *ProductUsecase) Archive(ctx context.Context, productID uint64) error {
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    // Check if already archived
    if product.Archived {
        return errors.New("product already archived")
    }

    // Set archived flag
    product.Archived = true

    // Auto hide if still selling
    if product.SaleStatus == enums.EProductSelling {
        product.SaleStatus = enums.EProductNotSold
    }
    if product.RentStatus == enums.EProductRenting {
        product.RentStatus = enums.EProductNotRent
    }

    err = uc.productRepo.Update(ctx, product)
    if err != nil {
        return err
    }

    // Hide all active posts
    posts, _ := uc.postRepo.GetByProduct(ctx, productID)
    for _, post := range posts {
        if post.Status == enums.EPostActive {
            post.Hidden = true
            uc.postRepo.Update(ctx, &post)
        }
    }

    return nil
}
```

**3. Restore (khôi phục)**:
```go
// Restore from soft delete
func (uc *ProductUsecase) Restore(ctx context.Context, productID uint64) error {
    // Query with Unscoped to get deleted records
    var product Product
    err := uc.db.Unscoped().Where("id = ?", productID).First(&product).Error
    if err != nil {
        return err
    }

    if product.DeletedAt == nil {
        return errors.New("product is not deleted")
    }

    // Restore (set deleted_at = NULL)
    err = uc.db.Unscoped().Model(&product).Update("deleted_at", nil).Error
    if err != nil {
        return err
    }

    // Create history
    history := &RecordHistory{
        RecordID:   &productID,
        RecordType: enums.ERecordTypeProduct,
        ActionType: enums.EHistoryActionUpdate,
        Content:    []string{"Product restored from deletion"},
    }
    uc.historyRepo.Create(ctx, history)

    return nil
}

// Unarchive
func (uc *ProductUsecase) Unarchive(ctx context.Context, productID uint64) error {
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    if !product.Archived {
        return errors.New("product is not archived")
    }

    product.Archived = false
    return uc.productRepo.Update(ctx, product)
}
```

**Sự khác biệt**:

| Feature | Soft Delete | Archive |
|---------|-------------|----------|
| **Mục đích** | Xóa (có thể khôi phục) | Lưu trữ (không dùng nữa) |
| **Field** | deleted_at != NULL | archived = true |
| **Query** | Bị filter tự động | Cần filter thủ công |
| **Hiển thị** | Không hiển thị (hidden) | Không hiển thị (except archive view) |
| **Restore** | Restore() | Unarchive() |
| **Use case** | Xóa nhầm, clean up | Sản phẩm cũ, hết hạn |

**Query patterns**:
```go
// Active products (không deleted, không archived)
db.Where("deleted_at IS NULL AND archived = false")

// Archived products (không deleted, nhưng archived)
db.Where("deleted_at IS NULL AND archived = true")

// Deleted products (soft deleted)
db.Unscoped().Where("deleted_at IS NOT NULL")

// All products including deleted and archived
db.Unscoped()
```

**Best practices**:
1. **Soft delete**: Cho phép khôi phục trong 30 ngày, sau đó hard delete (cronjob)
2. **Archive**: Giữ vĩnh viễn nhưng không hiển thị trong list thường
3. **Permission**: Chỉ owner hoặc admin có thể delete/archive
4. **Validation**: Không delete/archive product đang có giao dịch active

**Transfer Ownership** Product sang user/group/organization khác:

**1. Transfer usecase**:
```go
func (uc *ProductUsecase) TransferOwnership(ctx context.Context, productID uint64, newOwnerID uint64, newOwnerOf enums.EOwnerOf) error {
    return uc.db.Transaction(func(tx *gorm.DB) error {
        // 1. Get product
        product, err := uc.productRepo.GetByID(ctx, productID)
        if err != nil {
            return err
        }

        // 2. Check current owner permission
        profileID := _utils.GetProfileIdWithContext(ctx)
        if product.OwnerID != profileID {
            // Check if admin
            isAdmin := uc.checkAdminPermission(profileID)
            if !isAdmin {
                return errors.New("no permission to transfer")
            }
        }

        // 3. Validate new owner exists
        err = uc.validateOwner(ctx, newOwnerID, newOwnerOf)
        if err != nil {
            return err
        }

        // 4. Store old owner
        oldOwnerID := product.OwnerID
        oldOwnerOf := product.OwnerOf

        // 5. Update product ownership
        product.OwnerID = newOwnerID
        product.OwnerOf = newOwnerOf

        err = uc.productRepo.Update(ctx, product)
        if err != nil {
            return err
        }

        // 6. Update ProductUser/ProductOrganization
        // Remove old owner access
        if oldOwnerOf == enums.EOwnerOfMember {
            tx.Where("product_id = ? AND profile_id = ?", productID, oldOwnerID).
                Delete(&ProductUser{})
        } else if oldOwnerOf == enums.EOwnerOfOrgnization {
            tx.Where("product_id = ? AND organization_id = ?", productID, oldOwnerID).
                Delete(&ProductOrganization{})
        }

        // Add new owner access
        if newOwnerOf == enums.EOwnerOfMember {
            productUser := &ProductUser{
                ProductID: productID,
                ProfileID: newOwnerID,
                IsOwner:   true,
                RoleID:    4, // Owner role
            }
            tx.Create(productUser)
        } else if newOwnerOf == enums.EOwnerOfOrgnization {
            productOrg := &ProductOrganization{
                ProductID:      productID,
                OrganizationID: newOwnerID,
                IsOwner:        true,
                RoleID:         4,
            }
            tx.Create(productOrg)
        }

        // 7. Create history
        history := &RecordHistory{
            RecordID:   &productID,
            RecordType: enums.ERecordTypeProduct,
            ActionType: enums.EHistoryActionUpdate,
            Content: []string{
                fmt.Sprintf("Ownership transferred from %d (%d) to %d (%d)",
                    oldOwnerID, oldOwnerOf, newOwnerID, newOwnerOf),
            },
        }
        uc.historyRepo.Create(ctx, history)

        return nil
    })
}
```

**2. Validate owner helper**:
```go
func (uc *ProductUsecase) validateOwner(ctx context.Context, ownerID uint64, ownerOf enums.EOwnerOf) error {
    switch ownerOf {
    case enums.EOwnerOfMember:
        // Check member exists in organization
        var member Member
        err := uc.db.Where("id = ? AND deleted_at IS NULL", ownerID).First(&member).Error
        if err != nil {
            return errors.New("member not found")
        }

    case enums.EOwnerOfGroup:
        // Check group exists
        var group Group
        err := uc.db.Where("id = ? AND deleted_at IS NULL", ownerID).First(&group).Error
        if err != nil {
            return errors.New("group not found")
        }

    case enums.EOwnerOfOrgnization:
        // Check organization exists
        var org Organization
        err := uc.db.Where("id = ? AND deleted_at IS NULL", ownerID).First(&org).Error
        if err != nil {
            return errors.New("organization not found")
        }

    default:
        return errors.New("invalid owner_of type")
    }

    return nil
}
```

**3. Bulk transfer (nhiều products cùng lúc)**:
```go
func (uc *ProductUsecase) BulkTransferOwnership(ctx context.Context, productIDs []uint64, newOwnerID uint64, newOwnerOf enums.EOwnerOf) error {
    // Validate new owner
    err := uc.validateOwner(ctx, newOwnerID, newOwnerOf)
    if err != nil {
        return err
    }

    // Transfer each product
    for _, productID := range productIDs {
        err = uc.TransferOwnership(ctx, productID, newOwnerID, newOwnerOf)
        if err != nil {
            // Log error but continue
            log.Printf("Failed to transfer product %d: %v", productID, err)
        }
    }

    return nil
}
