```go
func (uc *ProductUsecase) GrantUserAccess(ctx context.Context, productID, profileID uint64, roleID uint64) error {
    // Check product exists
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    // Check current user is owner or has permission
    currentProfileID := _utils.GetProfileIdWithContext(ctx)
    if product.OwnerID != currentProfileID {
        return errors.New("no permission to grant access")
    }

    // Check if access already exists
    var existing ProductUser
    err = uc.db.Where("profile_id = ? AND product_id = ?", profileID, productID).First(&existing).Error
    if err == nil {
        // Update existing
        existing.RoleID = roleID
        return uc.db.Save(&existing).Error
    }

    // Create new access
    productUser := &ProductUser{
        ProductID: productID,
        ProfileID: profileID,
        IsOwner:   false,
        RoleID:    roleID,
    }

    return uc.db.Create(productUser).Error
}
```

