func (uc *ProductUsecase) RevokeUserAccess(ctx context.Context, productID, profileID uint64) error {
    // Check permission
    currentProfileID := _utils.GetProfileIdWithContext(ctx)
    product, _ := uc.productRepo.GetByID(ctx, productID)
    if product.OwnerID != currentProfileID {
        return errors.New("no permission")
    }

    // Cannot revoke owner access
    var productUser ProductUser
    err := uc.db.Where("profile_id = ? AND product_id = ?", profileID, productID).First(&productUser).Error
    if err != nil {
        return errors.New("access not found")
    }

    if productUser.IsOwner {
        return errors.New("cannot revoke owner access")
    }

    // Soft delete
    return uc.db.Delete(&productUser).Error
}
```

