func (r *ProductRepo) GetByIDWithAccessCheck(ctx context.Context, productID, profileID uint64) (*Product, error) {
    var product Product

    // Query product và check access
    err := r.DB.Where("products.id = ? AND products.deleted_at IS NULL", productID).
        Where("(products.owner_id = ? AND products.owner_of = ?) OR EXISTS (SELECT 1 FROM product_user WHERE product_user.product_id = products.id AND product_user.profile_id = ? AND product_user.deleted_at IS NULL)",
            profileID, enums.EOwnerOfMember, profileID).
        First(&product).Error

    if err != nil {
        return nil, err
    }

    return &product, nil
}
