func (uc *ProductUsecase) ShareProduct(ctx context.Context, productID, toUserID uint64, fields []string, permissions []string, commission float32) error {
    product, err := uc.productRepo.GetByID(ctx, productID)
    if err != nil {
        return err
    }

    // Check owner permission
    fromProfileID := _utils.GetProfileIdWithContext(ctx)
    if product.OwnerID != fromProfileID {
        return errors.New("no permission to share")
    }

    // Validate fields
    validFields := []string{"name", "address", "area", "price", "description"}
    for _, field := range fields {
        if !contains(validFields, field) {
            return fmt.Errorf("invalid field: %s", field)
        }
    }

    // Create sharing
    sharing := &SharingAccess{
        DomainID:    productID,
        Domain:      enums.EDomainProduct,
        FromType:    enums.EOwnerOfMember,
        FromId:      fromProfileID,
        ToType:      enums.EOwnerOfMember,
        ToId:        toUserID,
        Commission:  commission,
    }
    sharing.SetFields(fields)        // name,address,area,price
    sharing.SetPermissions(permissions) // view,edit

    return uc.sharingRepo.Create(ctx, sharing)
}
```

