func (r *ProductRepo) GetSharedProduct(ctx context.Context, productID, userID uint64) (*ProductDTO, error) {
    // Check sharing
    var sharing SharingAccess
    err := r.DB.Where("domain_id = ? AND domain = ? AND to_id = ? AND deleted_at IS NULL",
        productID, enums.EDomainProduct, userID).First(&sharing).Error
    if err != nil {
        return nil, errors.New("no sharing found")
    }

    // Get product
    var product Product
    err = r.DB.Where("id = ? AND deleted_at IS NULL", productID).First(&product).Error
    if err != nil {
        return nil, err
    }

    // Filter fields based on sharing
    allowedFields := sharing.GetFields()
    dto := &ProductDTO{
        ID: product.ID,
    }

    if contains(allowedFields, "name") {
        dto.Name = product.Name
    }
    if contains(allowedFields, "address") {
        dto.Address = product.Address
    }
    if contains(allowedFields, "area") {
        dto.Area = product.Area
    }
    if contains(allowedFields, "price") {
        // Load price
        if product.LastPriceID != nil {
            var price ProductPrice
            r.DB.First(&price, *product.LastPriceID)
            dto.SalePrice = price.SalePrice
            dto.RentPrice = price.RentPrice
        }
    }
    // ... other fields

    // Hide sensitive fields not in allowed list
    // Do NOT return: ImportPrice, PrivateNote, InternalDocs

    return dto, nil
}
