func (r *ProductRepo) GetSharedToMe(ctx context.Context, userID uint64) ([]ProductDTO, error) {
    // Get sharing records
    var sharings []SharingAccess
    err := r.DB.Where("to_id = ? AND domain = ? AND deleted_at IS NULL",
        userID, enums.EDomainProduct).Find(&sharings).Error
    if err != nil {
        return nil, err
    }

    if len(sharings) == 0 {
        return []ProductDTO{}, nil
    }

    // Get product IDs
    productIDs := make([]uint64, len(sharings))
    sharingMap := make(map[uint64]*SharingAccess)
    for i, s := range sharings {
        productIDs[i] = s.DomainID
        sharingMap[s.DomainID] = &sharings[i]
    }

    // Get products
    var products []Product
    err = r.DB.Where("id IN (?) AND deleted_at IS NULL", productIDs).Find(&products).Error
    if err != nil {
        return nil, err
    }

    // Map to DTOs with field filtering
    dtos := make([]ProductDTO, len(products))
    for i, product := range products {
        sharing := sharingMap[product.ID]
        dtos[i] = filterProductFields(&product, sharing.GetFields())
        dtos[i].Commission = sharing.Commission // Show commission
    }

    return dtos, nil
}
